grid=[[8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,8,8,5,8,8,8,8,8,5,8,8],[8,5,5,8,8,8,8,8,5,8,8,5,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,5,8,8,8]]
out=[r[:] for r in grid]
# fill intervals between consecutive 5s in rows/cols
for i,row in enumerate(grid):
    xs=[j for j,v in enumerate(row) if v==5]
    for a,b in zip(xs,xs[1:]):
        for j in range(a+1,b): out[i][j]=3
for j in range(len(grid[0])):
    ys=[i for i in range(len(grid)) if grid[i][j]==5]
    for a,b in zip(ys,ys[1:]):
        for i in range(a+1,b): out[i][j]=3
out
